create table if not exists public.food_calorie_daily_free_usage(usage_day date not null default (now() at time zone 'utc')::date,account_id uuid null,ip_hash text not null check(length(ip_hash)=64),created_at timestamptz not null default now(),constraint food_calorie_free_account_day unique nulls not distinct(usage_day,account_id),constraint food_calorie_free_ip_day unique(usage_day,ip_hash));
