revoke all on public.food_calorie_daily_free_usage from public,anon,authenticated;grant all on public.food_calorie_daily_free_usage to service_role;
create or replace function public.claim_food_calorie_daily_free_v15(p_account_id uuid,p_ip_hash text) returns boolean language plpgsql security definer set search_path=public as $$ begin if p_ip_hash is null or length(p_ip_hash)<>64 then return false; end if; if exists(select 1 from public.food_calorie_daily_free_usage where usage_day=(now() at time zone 'utc')::date and ip_hash=p_ip_hash) then return false; end if; if p_account_id is not null and exists(select 1 from public.food_calorie_daily_free_usage where usage_day=(now() at time zone 'utc')::date and account_id=p_account_id) then return false; end if; insert into public.food_calorie_daily_free_usage(usage_day,account_id,ip_hash) values((now() at time zone 'utc')::date,p_account_id,p_ip_hash); return true; exception when unique_violation then return false; end $$;
